const TAXILA_STATS=[{label:"Major Settlements",value:"3"},{label:"Active Years",value:"~1,100"},{label:"Ruling Powers",value:"7"},{label:"UNESCO Status",value:"Since 1980"}],TAXILA_SETTLEMENTS=[{id:"bhir-mound",name:"Bhir Mound",period:"c. 6th century BCE – 2nd century BCE",rulers:"Achaemenid Persia, Mauryan Empire",layout:"Irregular, organically grown street plan with narrow winding lanes, typical of early South Asian cities that developed without centralized town planning.",desc:"The oldest of Taxila's three cities, Bhir Mound represents the earliest urban settlement at the site, flourishing under Achaemenid Persian influence and later as a provincial center of the Mauryan Empire.",finds:"Excavations uncovered houses of rubble masonry, silver punch-marked coins, and everyday artifacts reflecting a bustling, unplanned trading town predating Hellenistic influence in the region."},{id:"sirkap",name:"Sirkap",period:"c. 2nd century BCE – 1st century CE",rulers:"Indo-Greeks, Indo-Scythians, Indo-Parthians",layout:"Laid out on a Hippodamian (Greek grid) plan with a main avenue and perpendicular side streets, reflecting direct Hellenistic urban planning traditions introduced by Indo-Greek rulers.",desc:"Built by the Indo-Greek king Demetrius after the decline of Bhir Mound, Sirkap became a cosmopolitan city blending Greek, Persian, Scythian, and Indian architectural and religious traditions side by side.",finds:"The site preserves the famous 'Shrine of the Double-Headed Eagle' (a Buddhist stupa with Greek, Persian, and Indian decorative motifs combined), along with Buddhist stupas, Jain temples, and Hindu shrines within the same city walls."},{id:"sirsukh",name:"Sirsukh",period:"c. 1st century CE – 5th century CE",rulers:"Kushan Empire",layout:"A large fortified rectangular city with massive rubble-and-stone walls up to 6 meters thick and rounded bastions, reflecting Central Asian military-style urban design.",desc:"Founded by the Kushans as Taxila's final and largest city, Sirsukh reflects the empire's Central Asian architectural heritage and served as a major hub during the height of Kushan patronage of Buddhism.",finds:"Though less excavated than Sirkap due to continued agricultural use of the land, surveys have revealed massive fortification walls and evidence of the city's role in Kushan-era trade and administration."}],TAXILA_TRADE_ROUTES=[{id:"grand-trunk",name:"Uttarapatha (Grand Trunk precursor)",connects:"Taxila to the Gangetic Plain and Pataliputra",note:"The great northern highway of ancient India, linking Taxila eastward to Magadha and the Mauryan capital, carrying goods, administrators, and ideas along a route later formalized as the Grand Trunk Road."},{id:"silk-road-west",name:"Silk Road (Western Branch via Bactria)",connects:"Taxila to Bactria, Persia, and the Mediterranean",note:"Taxila sat at a critical junction of the Silk Road's southern routes, connecting Central Asian and Persian trade networks to the Indian subcontinent through the Khyber and Kabul river valleys."},{id:"silk-road-north",name:"Silk Road (Northern Branch via Kashmir)",connects:"Taxila to Kashmir, the Karakoram, and Central Asia",note:"A mountain route linking Taxila to Central Asian oasis cities via Kashmir and the high passes of the Karakoram, used heavily during the Kushan period for Buddhist pilgrimage and trade alike."},{id:"indus-route",name:"Indus River Trade Corridor",connects:"Taxila to the Arabian Sea ports via the Indus",note:"A southbound corridor following the Indus River system toward coastal ports, allowing Gandharan goods and Buddhist art motifs to reach maritime trade networks extending to the Roman world."}],TAXILA_BUDDHIST_SITES=[{name:"Dharmarajika Stupa & Monastery",note:"Traditionally linked to relics of the Buddha enshrined by Emperor Ashoka, this vast stupa-and-monastery complex became one of the most important Buddhist pilgrimage sites in Gandhara."},{name:"Jaulian Monastery",note:"A hillside monastic complex renowned for its stucco relief sculptures of the Buddha and donors, offering some of the best-preserved Gandharan Buddhist art at the site."},{name:"Mohra Muradu Monastery",note:"A smaller, secluded monastery known for finely preserved stucco images, illustrating the spread of monastic institutions into the hills surrounding the main cities."},{name:"Shrine of the Double-Headed Eagle (Sirkap)",note:"A stupa within Sirkap city itself, whose facade combines a Buddhist stupa form with Greek pilasters, Persian crenellations, and an Indian torana gateway, symbolizing Taxila's cultural fusion."}],TAXILA_LEARNING={intro:"Taxila is traditionally remembered in Indian literary tradition as a center of learning where teachers instructed students in subjects ranging from the Vedas and grammar to medicine, archery, law, and politics, though it functioned as a constellation of individual teacher-student relationships rather than a single formal institution like later Nalanda.",figures:[{name:"Panini",note:"The celebrated Sanskrit grammarian, traditionally associated with the Taxila region, whose Ashtadhyayi systematized Sanskrit grammar with a precision still studied today."},{name:"Chanakya (Kautilya)",note:"Traditionally said to have taught at Taxila before becoming the strategist and mentor behind the rise of Chandragupta Maurya, later authoring the Arthashastra on statecraft."},{name:"Charaka (traditional association)",note:"Ancient medical tradition associates early Ayurvedic learning with teachers in the Taxila region, contributing to the region's reputation for medical education."}]},TAXILA_ARTIFACTS=[{id:"punch-marked-coins",name:"Silver Punch-Marked Coins",site:"Bhir Mound",desc:"Among the earliest coinage found in South Asia, stamped with symbols rather than inscriptions, reflecting Bhir Mound's role as an early trading settlement predating coin-portrait traditions."},{id:"double-headed-eagle",name:"Double-Headed Eagle Stupa Facade",site:"Sirkap",desc:"A carved stone facade combining a Buddhist stupa dome, Greek Corinthian pilasters, Persian crenellations, and an Indian torana arch — a single object embodying Taxila's cultural blending."},{id:"gandhara-buddha",name:"Gandharan Buddha Stucco Reliefs",site:"Jaulian & Mohra Muradu",desc:"Buddha and Bodhisattva images sculpted in the Greco-Buddhist Gandhara style, showing classical Hellenistic drapery and facial modeling fused with Buddhist iconography."},{id:"kushan-seals",name:"Kushan-Era Seals & Sealings",site:"Sirsukh region",desc:"Clay sealings bearing Kharoshthi and Brahmi inscriptions used to authenticate goods and correspondence, evidence of Taxila's administrative role within the Kushan trade network."},{id:"taxila-silver-vase",name:"Silver Vase of Taxila",site:"Bhir Mound / Sirkap deposits",desc:"Finely worked silver vessels recovered from Taxila's treasure deposits, illustrating the wealth accumulated through the city's control of trans-regional trade."}],TAXILA_TIMELINE=[{year:"c. 6th century BCE",title:"Early settlement (Bhir Mound)",desc:"Taxila emerges as an urban center under regional and later Achaemenid Persian administration."},{year:"c. 326 BCE",title:"Alexander's campaign",desc:"Alexander the Great's army passes through Taxila; Greek historians record it as a wealthy and hospitable city."},{year:"c. 321 – 185 BCE",title:"Mauryan rule",desc:"Taxila becomes a key provincial capital of the Mauryan Empire; Ashoka is traditionally said to have governed it as a prince."},{year:"c. 2nd century BCE",title:"Founding of Sirkap",desc:"The Indo-Greek king Demetrius founds Sirkap on a Hellenistic grid plan after Bhir Mound's decline."},{year:"c. 1st century BCE – 1st century CE",title:"Indo-Scythian & Indo-Parthian rule",desc:"Sirkap continues as the region's capital under successive Central Asian ruling dynasties, deepening cultural fusion."},{year:"c. 1st century CE",title:"Kushan conquest & founding of Sirsukh",desc:"The Kushan Empire absorbs Taxila and constructs the fortified city of Sirsukh as its new administrative center."},{year:"c. 1st – 5th century CE",title:"Height of Gandharan Buddhist art",desc:"Monasteries at Dharmarajika, Jaulian, and Mohra Muradu flourish, producing some of the finest Gandharan Buddhist sculpture."},{year:"c. 460s – 470s CE",title:"Hephthalite (Hun) invasions",desc:"Repeated Hun invasions devastate Taxila's monasteries and urban centers, beginning the region's long decline."},{year:"1863 – 1934 CE",title:"Rediscovery and excavation",desc:"Alexander Cunningham identifies the site in the 1860s; Sir John Marshall leads extensive systematic excavations from 1913–1934, uncovering all three cities."},{year:"1980 CE",title:"UNESCO World Heritage status",desc:"Taxila is inscribed as a UNESCO World Heritage Site, recognizing its exceptional testimony to cultural exchange across Central and South Asia."}],TAXILA_REFERENCES=[{text:"Marshall, Sir John. Taxila: An Illustrated Account of Archaeological Excavations. Cambridge University Press, 1951.",url:"https://www.jstor.org/"},{text:"UNESCO World Heritage Centre — Taxila.",url:"https://whc.unesco.org/en/list/139/"},{text:"Archaeological Survey of India / Directorate General of Archaeology, Pakistan — Taxila Site Reports.",url:"https://www.archaeology.gov.pk/"},{text:"Dani, Ahmad Hasan. The Historic City of Taxila. UNESCO / Sang-e-Meel Publications, 1986.",url:"https://whc.unesco.org/en/list/139/"}];